import re

if _item['json'].get('sample_code'):
    _item['json']['sample_code'] = re.sub(r'[^A-Z0-9_-]', '', str(_item['json']['sample_code']).strip().upper())

if _item['json'].get('researcher_email'):
    _item['json']['researcher_email'] = str(_item['json']['researcher_email']).strip().lower()

if _item['json'].get('operator_name'):
    _item['json']['operator_name'] = str(_item['json']['operator_name']).strip()

return _item

